{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    # Validate required fields
    for s in segments:
        if not all(k in s for k in ('name', 'importance', 'minimum', 'capacity')):
            raise ValueError('Missing required field in segment')
        try:
            s['importance'] = int(s['importance'])
            s['minimum'] = int(s['minimum'])
            s['capacity'] = int(s['capacity'])
        except (ValueError, TypeError):
            raise ValueError('Non-integer field in segment')
    # Budget validation
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError('Budget out of feasible range')
    # Allocate minima
    n = len(segments)
    allocated = [s['minimum'] for s in segments]
    total = sum_min
    # While budget remains
    while total < budget:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if allocated[i] < s['capacity']:
                score = s['importance'] / (allocated[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
                # Tie break by original order: already first encountered wins due to >
        if best_idx == -1:
            # Should not happen because total < budget and sum_cap >= budget
            raise ValueError('Infeasible: no capacity left')
        allocated[best_idx] += 1
        total += 1
    # Build result
    allocations = {segments[i]['name']: allocated[i] for i in range(n)}
    segment_order = [s['name'] for s in segments]
    return {
        'allocations': allocations,
        'segment_order': segment_order,
        'total_allocated': total
    }"
}
